// Code «Comprobar la búsqueda» (10 · Buscar apartado) · Run Once for All Items
// Recibe { id, texto, estado } de «Al buscar un apartado» y devuelve
// un item { por_numero, id, texto, estado } o para con error.

const ESTADOS = ['activo', 'liquidado', 'vencido'];
const entrada = $input.first().json;

// Un campo vacío puede llegar como null, "" o no llegar
const limpio = v => (v == null ? '' : String(v).trim());
const idTexto = limpio(entrada.id).replace(/^#/, '');
let texto = limpio(entrada.texto);
const estado = limpio(entrada.estado).toLowerCase();

if (!idTexto && !texto && !estado) {
  throw new Error('Buscar apartado: falta `id`, `texto` o `estado`');
}
if (estado && !ESTADOS.includes(estado)) {
  throw new Error(`Buscar apartado: estado no válido: «${estado}» (activo, liquidado o vencido)`);
}
let id = null;
if (idTexto) {
  if (!/^\d+$/.test(idTexto) || Number(idTexto) < 1) {
    throw new Error(`Buscar apartado: el id no es un entero positivo: «${idTexto}»`);
  }
  id = Number(idTexto);
}

// Teléfono de 9 cifras sin espacios → formato de la app (612 345 001)
if (/^\d{9}$/.test(texto)) texto = texto.replace(/^(\d{3})(\d{3})(\d{3})$/, '$1 $2 $3');

// Si llegan id y texto, manda el id
return [{ json: { por_numero: id != null, id, texto: id != null ? '' : texto, estado } }];

// Code «Preparar resultado» (10 · Buscar apartado) · Run Once for All Items
// Recibe la respuesta de «Leer apartado por número» o de «Buscar apartados por texto»
// (Include Response Headers and Status + Never Error) y devuelve siempre
// un item { total, apartados }. No recalcula `abonado` ni `pendiente`.

const CAMPOS = ['id', 'fecha', 'cliente', 'telefono', 'email', 'producto', 'talla', 'precio',
  'fecha_limite', 'estado', 'abonado', 'pendiente'];
const busqueda = $('Comprobar la búsqueda').first().json;

const cuerpo = b => {
  if (typeof b !== 'string') return b;
  try { return JSON.parse(b); } catch (e) { return b; }
};
// Mensaje de la app: {"detail": "..."} o, si falla la validación, {"detail": [{msg: ...}]}
function detalle(body) {
  const b = cuerpo(body);
  const d = b?.detail;
  if (Array.isArray(d)) return d.map(x => x.msg ?? JSON.stringify(x)).join('; ');
  return d ?? (typeof b === 'string' ? b : JSON.stringify(b));
}

const respuestas = $input.all().map(i => i.json);
const r = respuestas[0];
let lista;
if (r.statusCode === 200) {
  // Normalmente llega un item con la lista en `body`; por si n8n la reparte, se juntan todos
  lista = respuestas.flatMap(x => {
    const b = cuerpo(x.body);
    return Array.isArray(b) ? b : b ? [b] : [];
  });
} else if (r.statusCode === 404 && busqueda.por_numero) {
  lista = [];
} else {
  throw new Error(`Buscar apartado: la app respondió ${r.statusCode}: ${detalle(r.body)}`);
}

// Por número, el estado se filtra aquí (la API del detalle no lo admite)
if (busqueda.por_numero && busqueda.estado) lista = lista.filter(a => a.estado === busqueda.estado);

// Siempre los mismos campos, también si viene del detalle (sin `abonos` ni `vale`)
const apartados = lista.map(a => Object.fromEntries(CAMPOS.map(c => [c, a[c] ?? null])));

return [{ json: { total: apartados.length, apartados } }];
